def common(l1: list, l2: list):
    try:
        return sorted(set(l1) & set(l2))
    except TypeError:
        seen = set()
        result = []
        for x in l1:
            if x in l2 and x not in seen:
                try:
                    hash(x)
                    seen.add(x)
                except TypeError:
                    pass
                result.append(x)
        return sorted(result)
